function a(x : number, y : number, z : number) : string {
    if (x == z) {
        return ""
    } else if (x >= z - y) {
        return "#" + a(x+1, y, z)
    } else {
        return "$" + a(x+1, y, z)
    }
}

function b(x : number, y : number, z : number) : string {
    if (y == z) {
        return ""
    } else {
        return a(x, y, z) + "\n" + b(x, y+1, z) 
    }
}

